/**
 * `PulseCard(DATA)` from `technical_indicators` -- the fields `HeadlineMetricsStrip` doesn't cover
 * (that card is deliberately just the 5-stat "headline" strip mirroring `StockPreview`'s own
 * `headline_metrics`; everything else in `technical_indicators` was previously fetched, mapped, and
 * never rendered anywhere). 3 clusters, same divider-between-populated-clusters mechanism
 * `Fundamentals.kt`'s `Cluster`/`ClusterDivider` already uses. `dist_sma200_pct` stays exclusive to
 * `HeadlineMetricsStrip` -- not duplicated here.
 *
 * 💡 Its stat holder type is named `MomentumStat` (not the shorter `Stat` `Fundamentals.kt` uses) --
 * a `private` top-level class in Kotlin is only private to the *file* for functions/properties, but
 * still compiles to a single package-visible `.class` file for an actual class, so two files in the
 * same package both naming one `Stat` collide at the JVM level despite the source-level `private`.
 */
@Composable
fun MomentumAndTrend(indicators: DomainTechnicalIndicators?, modifier: Modifier = Modifier) {
    if (indicators == null) return

    var showGlossary by remember { mutableStateOf(false) }
    val title = stringResource(id = R.string.stock_detail_momentum_trend_title)
    val pulseColors = LocalPulseColors.current

    val momentumStats = listOfNotNull(
        indicators.macdSignal?.let {
            momentumStat(
                R.string.stock_detail_metric_macd_signal,
                it.replace('_', ' ').uppercase(Locale.US),
                "MACD_SIGNAL",
                macdSignalColor(it, pulseColors)
            )
        },
        indicators.macdHistogram?.let { momentumStat(R.string.stock_detail_metric_macd_histogram, formatDecimal(it), "MACD_HISTOGRAM") },
        indicators.barsSinceMacdCross?.let { momentumStat(R.string.stock_detail_metric_macd_bars, it.toString(), "MACD_BARS") }
    )
    val trendStats = listOfNotNull(
        indicators.distSma20Pct?.let { momentumStat(R.string.stock_detail_metric_dist_sma20, formatSignedPercent(it), "DIST_SMA20") },
        indicators.distSma50Pct?.let { momentumStat(R.string.stock_detail_metric_dist_sma50, formatSignedPercent(it), "DIST_SMA50") },
        indicators.high52w?.let { momentumStat(R.string.stock_detail_metric_52w_high, "$${formatDecimal(it)}", "52W_HIGH") },
        indicators.low52w?.let { momentumStat(R.string.stock_detail_metric_52w_low, "$${formatDecimal(it)}", "52W_LOW") }
    )
    val volumeStats = listOfNotNull(
        indicators.upDownVolumeRatio?.let { momentumStat(R.string.stock_detail_metric_up_down_volume, formatDecimal(it), "UP_DOWN_VOLUME") },
        indicators.volPercentile?.let { momentumStat(R.string.stock_detail_metric_vol_percentile, "$it%", "VOL_PERCENTILE") }
    )
    val hasAnyStats = momentumStats.isNotEmpty() || trendStats.isNotEmpty() || volumeStats.isNotEmpty()
    if (!hasAnyStats) return

    PulseCard(style = PulseCardStyle.DATA, modifier = modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            DataCardTitleWithInfo(title = title, onInfoClick = { showGlossary = true })
            Spacer()

            var precededByCluster = false
            if (momentumStats.isNotEmpty()) {
                Cluster(title = stringResource(id = R.string.stock_detail_cluster_momentum), stats = momentumStats)
                precededByCluster = true
            }
            if (trendStats.isNotEmpty()) {
                if (precededByCluster) ClusterDivider()
                Cluster(title = stringResource(id = R.string.stock_detail_cluster_trend), stats = trendStats)
                precededByCluster = true
            }
            if (volumeStats.isNotEmpty()) {
                if (precededByCluster) ClusterDivider()
                Cluster(title = stringResource(id = R.string.stock_detail_cluster_volume), stats = volumeStats)
            }
        }
    }

    if (showGlossary) {
        val entries = (momentumStats + trendStats + volumeStats)
            .map { GlossaryEntry(stringResource(id = it.labelRes), it.term) }
        StockAnalysisGlossaryBottomSheet(title = title, entries = entries, onDismiss = { showGlossary = false })
    }
}

private data class MomentumStat(val labelRes: Int, val value: String, val term: String, val valueColor: Color? = null)
private fun momentumStat(labelRes: Int, value: String, term: String, valueColor: Color? = null) = MomentumStat(labelRes, value, term, valueColor)

@Composable
private fun Cluster(title: String, stats: List<MomentumStat>) {
    if (stats.isEmpty()) return

    Column {
        SubClusterLabel(title = title)
        Spacer()
        FlowRow(
            horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_xlarge)),
            verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_medium))
        ) {
            stats.forEach { s ->
                Column(modifier = Modifier.width(dimensionResource(id = R.dimen.detail_stat_width))) {
                    Text(
                        text = s.value,
                        style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                        color = s.valueColor ?: MaterialTheme.colorScheme.onSurface
                    )
                    Text(
                        text = stringResource(id = s.labelRes),
                        style = MaterialTheme.typography.labelSmall,
                        color = LocalPulseColors.current.onSurfaceMuted
                    )
                }
            }
        }
        Spacer()
    }
}

private fun macdSignalColor(macdSignal: String, pulseColors: PulseColors): Color =
    when (macdSignal.uppercase(Locale.US)) {
        "BULLISH" -> pulseColors.signalBullishText
        "BEARISH" -> pulseColors.signalBearishText
        else -> pulseColors.signalNeutralText
    }

private fun formatDecimal(value: Double): String = String.format(Locale.US, "%.2f", value)
private fun formatSignedPercent(value: Double): String = "${if (value >= 0) "+" else ""}${formatDecimal(value)}%"

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
}

@Composable
private fun ClusterDivider() {
    HorizontalDivider(
        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f),
        thickness = dimensionResource(id = R.dimen.border_thin)
    )
    Spacer()
}

